import re
D="/config/workspace/IronClaude/.dev/worktrees/ci-followup/.dev/research/upstream-merge-impact/remaining-cleanup-validation/implementation-evidence/02-root-plugin/task4-runtime/runs/post-tier2-attempt-1/artifacts/adversarial"
FIELDS=["verdict","class","severity","rationale","evidence_missing","why_not_classifiable","next_evidence_needed","decision_needed_by_user","change","verifier"]
VAGUE=re.compile(r"\b(may|might|could|appropriate|as needed|properly|adequate|various|etc\.|should consider|best practices?|industry standard)\b",re.I)
CONC=re.compile(r"\d|`|\b\w+\.(py|md|yaml|log|patch|json)\b|\b[A-Z]-\d|\b(ValueError|ModuleNotFoundError|pytest|Bash|conftest|src|LOW|MEDIUM|HIGH|drift|Drift|Authorized|Necessary|Regression|true|false)\b|'[^']+'|\"")
def vals(t):
    out=[]
    for line in t.splitlines():
        if line.startswith("#"): continue
        m=re.match(r'^coverage_audit:\s*"(.*)"$',line)
        if m: out.append(("coverage_audit",m.group(1)))
        m=re.match(r'^\s+- "(.*)"$',line)
        if m: out.append(("risk",m.group(1)))
        for f in FIELDS:
            for mm in re.finditer(r'(?:^|[{,]\s*|^\s+)'+f+r':\s*("((?:[^"\\]|\\.)*)"|[^,}\n]+)',line):
                v=mm.group(2) if mm.group(2) is not None else mm.group(1)
                out.append((f,v.strip()))
    return out
for fn in ["variant-1-original.md","variant-2-original.md"]:
    t=open(f"{D}/{fn}").read()
    units=[]
    for f,v in vals(t):
        for c in re.split(r";\s+|(?<=[a-z\)'\]])\.\s+(?=[A-Z\[`'])",v):
            c=c.strip().rstrip(".")
            if c: units.append((f,c))
    nc=nv=nn=0
    print("=====",fn)
    for f,c in units:
        k="VAGUE" if VAGUE.search(c) else ("CONCRETE" if CONC.search(c) else "NEITHER")
        nc+=k=="CONCRETE"; nv+=k=="VAGUE"; nn+=k=="NEITHER"
        print(f"{k:8} [{f}] {c}")
    print("concrete",nc,"vague",nv,"neither",nn,"SR",round(nc/(nc+nv),4))
EOF
